clear;
clc;
close all;

%%\ Illustrative System Parameters
totalBandwidthHz = 1e6;      % Total bandwidth: 1 MHz
fdmaChannelHz    = 200e3;    % FDMA channel width: 200 kHz
tdmaSlots        = 8;        % Number of TDMA slots per frame
processingGain   = 64;       % CDMA processing gain
targetSIRdB      = 7;        % Minimum acceptable CDMA SIR

%%\ Capacity Estimates
fdmaUsers = floor(totalBandwidthHz / fdmaChannelHz);
tdmaUsers = tdmaSlots;

targetSIR = 10^(targetSIRdB / 10);
cdmaUsers = floor(1 + processingGain / targetSIR);

%%\ Display Results
fprintf('Illustrative Maximum Supported Users\n'); %[output:6a3f0837]
fprintf('-----------------------------------\n'); %[output:5d7170e0]
fprintf('FDMA : %d users\n', fdmaUsers); %[output:14d35273]
fprintf('TDMA : %d users\n', tdmaUsers); %[output:59b5a9a1]
fprintf('CDMA : %d users at a target SIR of %.1f dB\n\n', ... %[output:group:8cc3871a] %[output:0da72714]
    cdmaUsers, targetSIRdB); %[output:group:8cc3871a] %[output:0da72714]

%%\ CDMA SIR as Number of Users Increases
K = 2:30;
sirLinear = processingGain ./ (K - 1);
sirDb = 10 * log10(sirLinear);

%%\ Comparison Table
method = ["FDMA"; "TDMA"; "CDMA"];
supportedUsers = [fdmaUsers; tdmaUsers; cdmaUsers];

results = table(method, supportedUsers, ...
    'VariableNames', {'Method', 'SupportedUsers'});

disp(results); %[output:16e606ed]

%%\ Plot 1: Capacity Comparison
figure; %[output:66ba0ee8]
bar(categorical(method), supportedUsers); %[output:66ba0ee8]
ylabel('Maximum Supported Simultaneous Users'); %[output:66ba0ee8]
xlabel('Multiple Access Technique'); %[output:66ba0ee8]
title('FDMA, TDMA and CDMA Capacity Comparison'); %[output:66ba0ee8]
grid on; %[output:66ba0ee8]

%%\ Plot 2: CDMA SIR vs Number of Users
figure; %[output:2ef94e8e]
plot(K, sirDb, 'o-', 'LineWidth', 1.5); %[output:2ef94e8e]
hold on; %[output:2ef94e8e]
yline(targetSIRdB, '--r', 'Target SIR'); %[output:2ef94e8e]
xlabel('Number of Simultaneous CDMA Users (K)'); %[output:2ef94e8e]
ylabel('Estimated SIR (dB)'); %[output:2ef94e8e]
title('Estimated CDMA SIR vs Number of Users'); %[output:2ef94e8e]
grid on; %[output:2ef94e8e]
hold off; %[output:2ef94e8e]

